def add(uc,title,given,when,then,source='bff',basis='proposed-security',priority='P1',level='service-integration',ac=None,limits=None):
 ROWS.append({'id':f'RN-S{len(ROWS)+1:03}','title':title,'family':'security','use_case':uc,'level':level,'basis':basis,'ac_ids':ac or [],'given':given.split('|'),'when':when.split('|'),'then':then.split('|'),'sources':[SRC[k] for k in source.split(',')],'limits':limits or 'Defined adversarial check. No passing execution is inferred. Synthetic identities and isolated services only.','priority':priority,'execution_status':'NOT_RUN','definition_version':1})
add('UC-S01','Reject refresh replay after valid-access logout','Synthetic user A has unexpired access A and refresh A','A submits POST /v2/sso/logout with access A|A submits POST /v2/sso/relogin with refresh A','The logout response has result true|The relogin response has HTTP status 401|The relogin response issues zero access credentials','bff',basis='observed')
add('UC-S01','Reject refresh replay after expired-access logout','Synthetic user A has expired access A and unexpired refresh A','A submits POST /v2/sso/logout with access A|A submits POST /v2/sso/relogin with refresh A','The relogin response issues zero access credentials|The session revocation observation identifies the logout outcome','bff,logout')
add('UC-S01','Record logout failure when the revocation store fails','A has renewable credentials|The isolated revocation repository rejects writes','A submits logout|A attempts relogin with the copied refresh credential','The recorded response and revocation-store result identify the failed write|The security result reports whether renewed access was issued','bff',basis='policy-open',limits='Logout failure semantics and retry policy are unresolved. Acceptance is blocked; record observations without inventing an error code.')
add('UC-S01','Revoke the session when logout has no access but retains refresh','A has only an unexpired refresh credential','A requests logout|A replays the copied refresh credential','The security result records whether revocation occurred|The security result records the relogin status and issued-access count','bff,logout',basis='policy-open',limits='No-refresh logout or provider revocation contract is unavailable. Acceptance is blocked.')
add('UC-S01','Discard renewal success delivered after client logout','A has a relogin response held before client delivery','A selects Logout|The fixture releases the held relogin success','The browser access credential remains absent|The browser authenticated user remains absent','response,epoch',level='browser-e2e')
add('UC-S01','Reject server renewal after the session enters the deny list','A has valid refresh A|The server deny list contains A session identifier','A submits POST /v2/sso/relogin with refresh A','The response has HTTP status 401|The response issues zero access credentials','bff',basis='observed')
add('UC-S01','Resolve simultaneous server logout and relogin','A has valid refresh A|The fixture can hold the revocation write and renewal validation','A submits logout|A submits relogin|The fixture releases both operations in each order','The result records the validation and revocation commit order|The result records every issued access credential and its session identifier','bff',basis='policy-open',limits='Revocation linearization and treatment of already accepted renewal are unresolved. Acceptance is blocked.')
add('UC-S01','Reject revoked access when acquiring refresh','The deny list contains the session identifier in otherwise valid access A','A submits POST /v2/sso/refreshtoken with access A','The response has HTTP status 401|The response issues zero refresh credentials','bff',basis='observed')
add('UC-S01','Characterize replay of a replaced refresh credential','A has refresh R1|A obtains refresh R2 for the same session','A submits relogin with R1','The record identifies whether R1 remains accepted|The record identifies both refresh expiry values','bff',basis='policy-open',priority='P2',limits='Single-use rotation and replay detection are not specified. Do not assume replacement revokes R1. Acceptance is blocked.')
